const log = createLogger('IntegrationsClient');
const REQUEST_TIMEOUT_MS = 30_000;
const ACCOUNT_CHANGED_MESSAGE =
  'Rivet account changed. Retry with the intended account.';

export type NormalizedPin = {
  id: string;
  image_urls: string[];
  dominant_color: string | null;
  title: string | null;
  description: string | null;
  alt_text: string | null;
  link: string | null;
  local_path?: string;
};

export type NormalizedBoard = {
  id: string;
  name: string | null;
  description: string | null;
  privacy: string | null;
};

export type NormalizedAreNaChannel = {
  id: string;
  title: string | null;
  slug: string | null;
  visibility: string | null;
  description: string | null;
  owner_name: string | null;
  owner_slug: string | null;
  contents_count: number | null;
};

export type NormalizedAreNaContent = {
  id: string;
  kind: 'block' | 'channel';
  block_type: string | null;
  title: string | null;
  description: string | null;
  content: string | null;
  source_url: string | null;
  image_urls: string[];
  attachment_url: string | null;
  embed_url: string | null;
  alt_text: string | null;
};

export type NormalizedAreNaMeta = {
  current_page: number | null;
  per_page: number | null;
  total_pages: number | null;
  total_count: number | null;
  has_more_pages: boolean | null;
};

export type PinterestFetchFailureReason =
  | 'pin_not_accessible'
  | 'unsupported_url'
  | 'board_not_owned'
  | 'board_owner_unverified'
  | 'board_not_found'
  | 'rate_limited';

export type PinterestFetchResult =
  | { status: 'ok'; type: 'pin'; pins: NormalizedPin[] }
  | {
      status: 'ok';
      type: 'board';
      board: NormalizedBoard;
      pins: NormalizedPin[];
      page?: { nextCursor: string | null; isComplete: boolean };
    }
  | { status: 'not_connected' }
  | {
      status: 'error';
      message: string;
      reason?: PinterestFetchFailureReason;
      retryAfterMs?: number;
    };

export type AreNaFetchResult =
  | {
      status: 'ok';
      type: 'channel';
      channel: NormalizedAreNaChannel;
      contents: NormalizedAreNaContent[];
      meta: NormalizedAreNaMeta | null;
    }
  | {
      status: 'ok';
      type: 'block';
      contents: NormalizedAreNaContent[];
    }
  | { status: 'not_connected' }
  | {
      status: 'error';
      message: string;
      reason?: 'rate_limited';
      retryAfterMs?: number;
    };

export type IntegrationSummary = {
  externalAccountId?: string | null;
  provider: string;
  status: string;
  externalUsername: string | null;
  connectedAt: string;
};

export type IntegrationListResult =
  | { status: 'ok'; integrations: IntegrationSummary[] }
  | { status: 'error'; message: string };

export type IntegrationConnectResult =
  { status: 'ok'; authUrl: string } | { status: 'error'; message: string };

export type IntegrationDisconnectResult =
  | { status: 'ok' }
  | {
      status: 'error';
      reason: 'auth_required' | 'account_changed' | 'request_failed';
      message: string;
    };

export type IntegrationProvider = 'pinterest' | 'arena' | 'x';

const NormalizedPinSchema = z.object({
  id: z.string(),
  image_urls: z.array(z.string()),
  dominant_color: z.string().nullable(),
  title: z.string().nullable(),
  description: z.string().nullable(),
  alt_text: z.string().nullable(),
  link: z.string().nullable(),
  local_path: z.string().optional(),
});

const NormalizedBoardSchema = z.object({
  id: z.string(),
  name: z.string().nullable(),
  description: z.string().nullable(),
  privacy: z.string().nullable(),
});

const PinterestFetchResultSchema: z.ZodType<PinterestFetchResult> = z.union([
  z.object({
    status: z.literal('ok'),
    type: z.literal('pin'),
    pins: z.array(NormalizedPinSchema),
  }),
  z.object({
    status: z.literal('ok'),
    type: z.literal('board'),
    board: NormalizedBoardSchema,
    pins: z.array(NormalizedPinSchema),
    page: z
      .object({ nextCursor: z.string().nullable(), isComplete: z.boolean() })
      .optional(),
  }),
  z.object({ status: z.literal('not_connected') }),
  z.object({
    status: z.literal('error'),
    message: z.string(),
    reason: z
      .enum([
        'pin_not_accessible',
        'unsupported_url',
        'board_not_owned',
        'board_owner_unverified',
        'board_not_found',
        'rate_limited',
      ])
      .optional(),
    retryAfterMs: z.number().optional(),
  }),
]);

const NormalizedAreNaContentSchema = z.object({
  id: z.string(),
  kind: z.enum(['block', 'channel']),
  block_type: z.string().nullable(),
  title: z.string().nullable(),
  description: z.string().nullable(),
  content: z.string().nullable(),
  source_url: z.string().nullable(),
  image_urls: z.array(z.string()),
  attachment_url: z.string().nullable(),
  embed_url: z.string().nullable(),
  alt_text: z.string().nullable(),
});

const AreNaFetchResultSchema: z.ZodType<AreNaFetchResult> = z.union([
  z.object({
    status: z.literal('ok'),
    type: z.literal('channel'),
    channel: z.object({
      id: z.string(),
      title: z.string().nullable(),
      slug: z.string().nullable(),
      visibility: z.string().nullable(),
      description: z.string().nullable(),
      owner_name: z.string().nullable(),
      owner_slug: z.string().nullable(),
      contents_count: z.number().nullable(),
    }),
    contents: z.array(NormalizedAreNaContentSchema),
    meta: z
      .object({
        current_page: z.number().nullable(),
        per_page: z.number().nullable(),
        total_pages: z.number().nullable(),
        total_count: z.number().nullable(),
        has_more_pages: z.boolean().nullable(),
      })
      .nullable(),
  }),
  z.object({
    status: z.literal('ok'),
    type: z.literal('block'),
    contents: z.array(NormalizedAreNaContentSchema),
  }),
  z.object({ status: z.literal('not_connected') }),
  z.object({
    status: z.literal('error'),
    message: z.string(),
    reason: z.literal('rate_limited').optional(),
    retryAfterMs: z.number().optional(),
  }),
]);

const IntegrationListBodySchema = z.object({
  integrations: z
    .array(
      z.object({
        provider: z.unknown().optional(),
        status: z.unknown().optional(),
        externalAccountId: z.unknown().optional(),
        externalUsername: z.unknown().optional(),
        connectedAt: z.unknown().optional(),
      }),
    )
    .optional(),
});

const IntegrationConnectBodySchema = z.object({
  authUrl: z.string().min(1).optional(),
  message: z.string().optional(),
  error: z.string().optional(),
});

const IntegrationDisconnectBodySchema = z.object({ success: z.literal(true) });
const XDisconnectBodySchema = z.object({ status: z.literal('ok') });

const INTEGRATION_PROVIDERS: readonly IntegrationProvider[] = [
  'pinterest',
  'arena',
  'x',
];

export const isIntegrationProvider = (
  value: string,
): value is IntegrationProvider =>
  (INTEGRATION_PROVIDERS as readonly string[]).includes(value);

export class IntegrationsClient {
  private readonly proxyUrl: string;
  private readonly configManager = getConfigManager();
  private readonly authService: AuthService;

  constructor(options?: { proxyUrl?: string; authService?: AuthService }) {
    this.proxyUrl = options?.proxyUrl || this.configManager.getProxyUrl();
    this.authService = options?.authService ?? new AuthService(this.proxyUrl);
  }

  private async getBearerToken(): Promise<string | null> {
    const requestContext = getRequestAuthContext();
    let token = requestContext?.token ?? this.configManager.getAuthToken();
    if (token) {
      return token;
    }

    const profile = await this.authService.getValidatedProfile();
    token = getRequestAuthContext()?.token ?? this.configManager.getAuthToken();
    if (!profile || !token) {
      return null;
    }
    return token;
  }

  private async requestWithBearer(
    request: (bearer: string) => Promise<Response>,
    expectedAccountId?: string,
  ): Promise<Response | null> {
    const token = await this.getBearerToken();
    if (!token) {
      return null;
    }

    const updateAuth = captureAuthUpdate(this.configManager);
    const requestContext = getRequestAuthContext();
    const refreshToken =
      requestContext?.refreshToken ?? this.configManager.getRefreshToken();
    const response = await request(token);
    if (response.status !== 401) {
      return response;
    }

    if (!refreshToken) {
      return response;
    }

    const refreshed = await refreshAccessTokenViaProxy({
      refreshToken,
      proxyUrl: this.proxyUrl,
    });
    if (!refreshed) {
      return response;
    }

    if (
      expectedAccountId !== undefined &&
      this.configManager.getUserId() !== expectedAccountId
    )
      throw new Error(ACCOUNT_CHANGED_MESSAGE);
    updateAuth(refreshed);
    return request(refreshed.token);
  }

  async fetchPinterest(
    url: string,
    pagination?: { cursor?: string },
    cancellation?: AbortSignal,
  ): Promise<PinterestFetchResult> {
    const post = async (bearer: string): Promise<Response> =>
      fetch(`${this.proxyUrl}/api/integrations/pinterest/fetch`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${bearer}`,
        },
        body: JSON.stringify({ url, ...(pagination ? { pagination } : {}) }),
        signal: cancellation
          ? AbortSignal.any([
              cancellation,
              AbortSignal.timeout(REQUEST_TIMEOUT_MS),
            ])
          : AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });

    try {
      const response = await this.requestWithBearer(post);
      if (!response) {
        return { status: 'error', message: 'Not authenticated' };
      }

      await throwIfRateLimited(response);
      if (!response.ok) {
        const text = await response.text().catch(() => '');
        return {
          status: 'error',
          message: `Pinterest fetch failed (${response.status}): ${text.slice(0, 200)}`,
        };
      }

      return PinterestFetchResultSchema.parse(await response.json());
    } catch (error) {
      if (error instanceof ProviderRateLimit)
        return {
          status: 'error',
          reason: 'rate_limited',
          retryAfterMs: error.retryAfterMs,
          message: error.message,
        };
      log.warn('Pinterest fetch error:', error);
      return {
        status: 'error',
        message: errorMessage(error, 'Unknown error'),
      };
    }
  }

  async fetchArena(
    url: string,
    page?: number,
    cancellation?: AbortSignal,
  ): Promise<AreNaFetchResult> {
    const post = async (bearer: string): Promise<Response> =>
      fetch(`${this.proxyUrl}/api/integrations/arena/fetch`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${bearer}`,
        },
        body: JSON.stringify({ url, ...(page !== undefined ? { page } : {}) }),
        signal: cancellation
          ? AbortSignal.any([
              cancellation,
              AbortSignal.timeout(REQUEST_TIMEOUT_MS),
            ])
          : AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });

    try {
      const response = await this.requestWithBearer(post);
      if (!response) {
        return { status: 'error', message: 'Not authenticated' };
      }

      await throwIfRateLimited(response);
      if (!response.ok) {
        const text = await response.text().catch(() => '');
        return {
          status: 'error',
          message: `Are.na fetch failed (${response.status}): ${text.slice(0, 200)}`,
        };
      }

      return AreNaFetchResultSchema.parse(await response.json());
    } catch (error) {
      if (error instanceof ProviderRateLimit)
        return {
          status: 'error',
          reason: 'rate_limited',
          retryAfterMs: error.retryAfterMs,
          message: error.message,
        };
      log.warn('Are.na fetch error:', error);
      return {
        status: 'error',
        message: errorMessage(error, 'Unknown error'),
      };
    }
  }

  private async referenceRequest({
    provider,
    path,
    expectedAccountId,
    cursor,
    signal,
  }: {
    provider: AuthenticatedReferenceProvider;
    path: string;
    expectedAccountId?: string;
    cursor?: string;
    signal?: AbortSignal;
  }): Promise<unknown> {
    signal?.throwIfAborted();
    const query = new URLSearchParams({
      ...(expectedAccountId ? { expectedAccountId } : {}),
      ...(cursor ? { cursor } : {}),
    });
    const response = await this.requestWithBearer((bearer) =>
      fetch(
        `${this.proxyUrl}/api/integrations/references/${provider}/${path}?${query}`,
        {
          headers: { Authorization: `Bearer ${bearer}` },
          signal: AbortSignal.any([
            AbortSignal.timeout(REQUEST_TIMEOUT_MS),
            ...(signal ? [signal] : []),
          ]),
        },
      ),
    );
    if (!response)
      throw new Error('Sign in to Rivet to connect design references');
    await throwIfRateLimited(response);
    const data: unknown = await response.json();
    if (!response.ok) {
      const failure = z
        .object({ reason: z.enum(['not_connected', 'account_changed']) })
        .safeParse(data);
      if (failure.success)
        throw new ReferenceConnectionError(failure.data.reason);
      throw new Error(
        'Reference collections are unavailable. Check the connection and update the Rivet proxy.',
      );
    }
    return data;
  }

  async discoverReferenceCollections(input: {
    provider: AuthenticatedReferenceProvider;
    expectedAccountId?: string;
    cursor?: string;
    signal?: AbortSignal;
  }) {
    return ReferenceCatalogPageSchema.parse(
      await this.referenceRequest({ ...input, path: 'collections' }),
    );
  }

  async readReferenceCollection(input: {
    provider: AuthenticatedReferenceProvider;
    expectedAccountId: string;
    collectionId: string;
    cursor?: string;
    signal?: AbortSignal;
  }) {
    return ReferenceContentsPageSchema.parse(
      await this.referenceRequest({
        ...input,
        path: `collections/${encodeURIComponent(input.collectionId)}/references`,
      }),
    );
  }

  async referenceAccount(input: {
    provider: AuthenticatedReferenceProvider;
    expectedAccountId: string;
    signal?: AbortSignal;
  }) {
    return ReferenceProfileSchema.parse(
      await this.referenceRequest({ ...input, path: 'account' }),
    );
  }

  async discoverCosmos({
    url,
    cursor,
    signal,
  }: CosmosDiscoveryInput): Promise<CosmosProfilePage> {
    signal?.throwIfAborted();
    const query = new URLSearchParams({ url });
    if (cursor) query.set('cursor', cursor);
    const response = await this.requestWithBearer((bearer) =>
      fetch(`${this.proxyUrl}/api/integrations/cosmos/profiles?${query}`, {
        headers: { Authorization: `Bearer ${bearer}` },
        signal: AbortSignal.any([
          AbortSignal.timeout(REQUEST_TIMEOUT_MS),
          ...(signal ? [signal] : []),
        ]),
      }),
    );
    if (!response)
      throw new Error('Sign in to Rivet to discover a public Cosmos profile');
    await throwIfRateLimited(response);
    const data: unknown = await response.json();
    if (!response.ok) {
      const message =
        data &&
        typeof data === 'object' &&
        'message' in data &&
        typeof data.message === 'string'
          ? data.message
          : 'Cosmos profile discovery is unavailable; update the Rivet proxy and retry';
      throw new Error(message);
    }
    return CosmosProfilePageSchema.parse(data);
  }

  async fetchCosmos({
    url,
    collectionId,
    cursor,
    signal,
  }: CosmosFetchInput): Promise<CosmosResult> {
    try {
      const route = collectionId
        ? `/collections/${encodeURIComponent(collectionId)}/elements`
        : '/collections';
      const query = new URLSearchParams(collectionId ? {} : { url });
      if (cursor) query.set('cursor', cursor);
      const response = await this.requestWithBearer((bearer) =>
        fetch(`${this.proxyUrl}/api/integrations/cosmos${route}?${query}`, {
          headers: { Authorization: `Bearer ${bearer}` },
          signal: AbortSignal.any([
            AbortSignal.timeout(REQUEST_TIMEOUT_MS),
            ...(signal ? [signal] : []),
          ]),
        }),
      );
      if (!response) return { status: 'error', message: 'Not authenticated' };
      await throwIfRateLimited(response);
      const parsed = CosmosResultSchema.safeParse(await response.json());
      if (!parsed.success || (!response.ok && parsed.data.status !== 'error'))
        throw new Error('Invalid Cosmos response');
      return parsed.data;
    } catch (error) {
      signal?.throwIfAborted();
      if (error instanceof ProviderRateLimit)
        return {
          status: 'error',
          reason: 'rate_limited',
          message: error.message,
          retryAfterMs: error.retryAfterMs,
        };
      return {
        status: 'error',
        reason: 'provider_unavailable',
        message:
          'Cosmos collections could not be loaded. Check the public collection URL and retry.',
      };
    }
  }

  async fetchXBookmarks({
    expectedAccountId,
    cursor,
    signal,
  }: {
    expectedAccountId: string;
    cursor?: string;
    signal?: AbortSignal;
  }): Promise<XBookmarksResult> {
    try {
      const response = await this.requestWithBearer((bearer) =>
        fetch(`${this.proxyUrl}/api/integrations/x/fetch`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${bearer}`,
          },
          body: JSON.stringify({
            expectedAccountId,
            ...(cursor ? { cursor } : {}),
          }),
          signal: signal
            ? AbortSignal.any([signal, AbortSignal.timeout(REQUEST_TIMEOUT_MS)])
            : AbortSignal.timeout(REQUEST_TIMEOUT_MS),
        }),
      );
      if (!response) return { status: 'error', message: 'Not authenticated' };
      await throwIfRateLimited(response);
      const parsed = XBookmarksResultSchema.safeParse(await response.json());
      if (!parsed.success || (!response.ok && parsed.data.status !== 'error'))
        throw new Error('Invalid X bookmark response');
      return parsed.data;
    } catch (error) {
      signal?.throwIfAborted();
      if (error instanceof ProviderRateLimit)
        return {
          status: 'error',
          reason: 'rate_limited',
          retryAfterMs: error.retryAfterMs,
          message: error.message,
        };
      return {
        status: 'error',
        message:
          'X bookmarks could not be loaded. Check the X connection in Rivet and retry.',
      };
    }
  }

  async listIntegrations(): Promise<IntegrationListResult> {
    const get = async (bearer: string): Promise<Response> =>
      fetch(`${this.proxyUrl}/api/integrations`, {
        method: 'GET',
        headers: { Authorization: `Bearer ${bearer}` },
      });

    try {
      const response = await this.requestWithBearer(get);
      if (!response) {
        return { status: 'error', message: 'Not authenticated' };
      }

      if (!response.ok) {
        const text = await response.text().catch(() => '');
        return {
          status: 'error',
          message: `Integration status failed (${response.status}): ${text.slice(0, 200)}`,
        };
      }

      const body = IntegrationListBodySchema.parse(await response.json());
      return {
        status: 'ok',
        integrations: (body.integrations ?? []).map((integration) => ({
          provider: String(integration.provider ?? ''),
          status: String(integration.status ?? ''),
          externalAccountId:
            typeof integration.externalAccountId === 'string'
              ? integration.externalAccountId
              : null,
          externalUsername:
            typeof integration.externalUsername === 'string'
              ? integration.externalUsername
              : null,
          connectedAt: String(integration.connectedAt ?? ''),
        })),
      };
    } catch (error) {
      log.warn('Integration status error:', error);
      return {
        status: 'error',
        message: errorMessage(error, 'Unknown error'),
      };
    }
  }

  async connect(
    provider: IntegrationProvider,
  ): Promise<IntegrationConnectResult> {
    const post = async (bearer: string): Promise<Response> =>
      fetch(`${this.proxyUrl}/api/integrations/${provider}/connect`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${bearer}`,
        },
        body: JSON.stringify({ flow: 'popup' }),
      });

    try {
      const response = await this.requestWithBearer(post);
      if (!response) {
        return { status: 'error', message: 'Not authenticated' };
      }
      const parsed = IntegrationConnectBodySchema.safeParse(
        await response.json().catch(() => ({})),
      );
      const body = parsed.success ? parsed.data : {};
      if (!response.ok || !body.authUrl) {
        const message =
          (typeof body.message === 'string' && body.message) ||
          (typeof body.error === 'string' && body.error) ||
          `Could not start ${provider} connect (${response.status})`;
        return { status: 'error', message };
      }
      return { status: 'ok', authUrl: body.authUrl };
    } catch (error) {
      log.warn('Integration connect error:', error);
      return {
        status: 'error',
        message: errorMessage(error, 'Unknown error'),
      };
    }
  }

  async disconnect(
    provider: IntegrationProvider,
    expectedAccountId?: string,
  ): Promise<IntegrationDisconnectResult> {
    const isAccountCurrent = () =>
      expectedAccountId === undefined ||
      this.configManager.getUserId() === expectedAccountId;
    const accountChanged: IntegrationDisconnectResult = {
      status: 'error',
      reason: 'account_changed',
      message: ACCOUNT_CHANGED_MESSAGE,
    };
    const requestFailed: IntegrationDisconnectResult = {
      status: 'error',
      reason: 'request_failed',
      message:
        'Could not confirm reference account disconnection. Check your Rivet sign-in and connection, then retry.',
    };
    const del = async (bearer: string): Promise<Response> => {
      if (!isAccountCurrent()) throw new Error(accountChanged.message);
      return fetch(`${this.proxyUrl}/api/integrations/${provider}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${bearer}` },
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });
    };

    try {
      if (!isAccountCurrent()) return accountChanged;
      const response = await this.requestWithBearer(del, expectedAccountId);
      if (!response || response.status === 401)
        return {
          status: 'error',
          reason: 'auth_required',
          message: 'Sign in to Rivet before disconnecting a reference account.',
        };
      if (!response.ok) return requestFailed;
      const acknowledgement: unknown = await response.json();
      const schema =
        provider === 'x'
          ? XDisconnectBodySchema
          : IntegrationDisconnectBodySchema;
      if (!schema.safeParse(acknowledgement).success) return requestFailed;
      return { status: 'ok' };
    } catch {
      log.warn('Integration disconnect request failed');
      return isAccountCurrent() ? requestFailed : accountChanged;
    }
  }
}
